{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "Pentosan polysulfate sodium, a highly sulfated polysaccharide, had oral bioavailability of only 0.5–1% in healthy subjects after daily oral dosing, directly demonstrating that sulfated carbohydrate polymers are very poorly absorbed.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Acarbose, a polar carbohydrate-based drug, had absolute oral bioavailability below 2% in humans based on plasma and urinary recovery versus IV, showing that highly polar sugar-containing molecules fail to reach the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Glycyrrhizin, which contains glucuronic acid moieties and multiple polar groups, had an oral bioavailability of approximately 0.25% compared with injections in humans, providing direct evidence that glucuronide/sugar acid conjugates are essentially non-absorbed orally.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Furosemide acyl glucuronide, a glucuronide conjugate with a carboxylic acid, had an oral bioavailability of 0.15 ± 0.04 in humans, directly showing that glucuronic acid-containing polar conjugates have negligible systemic availability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Glucoraphanin, a sulfated glycoside, had a mean oral bioavailability of only about 5% in 50 human participants, supporting that sulfate ester plus sugar polarity severely limits oral absorption.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a sulfated N-acetylglucosamine-glucuronic acid disaccharide with extreme polarity, multiple ionizable groups, and very low predicted permeability. Multiple high-transfer human oral bioavailability studies on closely related sulfated polysaccharides, glucuronide conjugates, and polar glycosides consistently report F values below 5%, often below 1%. The direct experimental evidence strongly supports low oral bioavailability (<20%).",
  "evidence_gaps": [
    "No direct pharmacokinetic study of the exact query molecule was available, but close structural analogues with the same key functional groups were abundant.",
    "No evidence for active uptake or prodrug behavior that could overcome the severe permeability barrier was identified.",
    "Exact absolute F for the query is not measured, but all relevant analogues fall far below the 20% threshold."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

